import * as helpers from "./index.js";
export { resolveInterval as stablePublicName } from "./index.js";
// Preserve this unrelated homonym and the literal normalizeInterval.
function normalizeInterval() { return "normalizeInterval"; }
export function exerciseNavigationFixture() {
  retainedLocal(undefined, { start: new Date(0), end: new Date(1) }); helpers.resolveInterval(undefined, { start: new Date(0), end: new Date(1) });
